const express = require('express');
const app = express();

app.use(express.json());

function tokenize(input) {
  const tokens = [];
  let i = 0;

  while (i < input.length) {
    const ch = input[i];

    if (/\s/.test(ch)) {
      i += 1;
      continue;
    }

    const three = input.slice(i, i + 3);
    if (three === '===' || three === '!==') {
      tokens.push({ type: 'op', value: three });
      i += 3;
      continue;
    }

    const two = input.slice(i, i + 2);
    if (['&&', '||', '<=', '>=', '==', '!='].includes(two)) {
      tokens.push({ type: 'op', value: two });
      i += 2;
      continue;
    }

    if ('()[]!.<>+-*/%'.includes(ch)) {
      tokens.push({ type: 'op', value: ch });
      i += 1;
      continue;
    }

    if (ch === '"' || ch === "'") {
      const quote = ch;
      let value = '';
      i += 1;
      while (i < input.length) {
        if (input[i] === '\\') {
          const escaped = input[i + 1];
          const escapes = { n: '\n', r: '\r', t: '\t', b: '\b', f: '\f', v: '\v', '0': '\0' };
          value += Object.prototype.hasOwnProperty.call(escapes, escaped) ? escapes[escaped] : escaped;
          i += 2;
          continue;
        }
        if (input[i] === quote) break;
        value += input[i];
        i += 1;
      }
      if (input[i] !== quote) throw new Error('Unterminated string literal');
      i += 1;
      tokens.push({ type: 'literal', value });
      continue;
    }

    if (/\d/.test(ch) || (ch === '.' && /\d/.test(input[i + 1]))) {
      const match = input.slice(i).match(/^(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?/i);
      if (!match) throw new Error('Invalid number literal');
      tokens.push({ type: 'literal', value: Number(match[0]) });
      i += match[0].length;
      continue;
    }

    if (/[A-Za-z_$]/.test(ch)) {
      const match = input.slice(i).match(/^[A-Za-z_$][A-Za-z0-9_$]*/);
      const ident = match[0];
      if (ident === 'true') tokens.push({ type: 'literal', value: true });
      else if (ident === 'false') tokens.push({ type: 'literal', value: false });
      else if (ident === 'null') tokens.push({ type: 'literal', value: null });
      else tokens.push({ type: 'ident', value: ident });
      i += ident.length;
      continue;
    }

    throw new Error(`Unexpected character: ${ch}`);
  }

  tokens.push({ type: 'eof', value: '' });
  return tokens;
}

function evalRule(req) {
  const expr = req.body && req.body.rule;
  if (typeof expr !== 'string' || expr.trim() === '') {
    throw new Error('rule must be a non-empty string');
  }

  const tokens = tokenize(expr);
  let pos = 0;

  const peek = () => tokens[pos];
  const consume = (value) => {
    if (peek().value === value) {
      pos += 1;
      return true;
    }
    return false;
  };
  const expect = (value) => {
    if (!consume(value)) throw new Error(`Expected ${value}`);
  };

  const assertSafeProperty = (prop) => {
    if (['__proto__', 'prototype', 'constructor'].includes(String(prop))) {
      throw new Error('Unsafe property access');
    }
  };

  function parseExpression() {
    return parseLogicalOr();
  }

  function parseLogicalOr() {
    let left = parseLogicalAnd();
    while (consume('||')) {
      left = left || parseLogicalAnd();
    }
    return left;
  }

  function parseLogicalAnd() {
    let left = parseEquality();
    while (consume('&&')) {
      left = left && parseEquality();
    }
    return left;
  }

  function parseEquality() {
    let left = parseComparison();
    while (['==', '!=', '===', '!=='].includes(peek().value)) {
      const op = peek().value;
      pos += 1;
      const right = parseComparison();
      if (op === '==') left = left == right; // eslint-disable-line eqeqeq
      else if (op === '!=') left = left != right; // eslint-disable-line eqeqeq
      else if (op === '===') left = left === right;
      else left = left !== right;
    }
    return left;
  }

  function parseComparison() {
    let left = parseAdditive();
    while (['<', '<=', '>', '>='].includes(peek().value)) {
      const op = peek().value;
      pos += 1;
      const right = parseAdditive();
      if (op === '<') left = left < right;
      else if (op === '<=') left = left <= right;
      else if (op === '>') left = left > right;
      else left = left >= right;
    }
    return left;
  }

  function parseAdditive() {
    let left = parseMultiplicative();
    while (['+', '-'].includes(peek().value)) {
      const op = peek().value;
      pos += 1;
      const right = parseMultiplicative();
      left = op === '+' ? left + right : left - right;
    }
    return left;
  }

  function parseMultiplicative() {
    let left = parseUnary();
    while (['*', '/', '%'].includes(peek().value)) {
      const op = peek().value;
      pos += 1;
      const right = parseUnary();
      if (op === '*') left = left * right;
      else if (op === '/') left = left / right;
      else left = left % right;
    }
    return left;
  }

  function parseUnary() {
    if (consume('!')) return !parseUnary();
    if (consume('-')) return -parseUnary();
    if (consume('+')) return +parseUnary();
    return parseMember();
  }

  function parseMember() {
    let value = parsePrimary();
    while (true) {
      if (consume('.')) {
        const token = peek();
        if (token.type !== 'ident') throw new Error('Expected property name');
        pos += 1;
        assertSafeProperty(token.value);
        value = value == null ? undefined : value[token.value];
      } else if (consume('[')) {
        const prop = parseExpression();
        expect(']');
        assertSafeProperty(prop);
        value = value == null ? undefined : value[prop];
      } else {
        break;
      }
    }
    return value;
  }

  function parsePrimary() {
    const token = peek();
    if (token.type === 'literal') {
      pos += 1;
      return token.value;
    }
    if (token.type === 'ident') {
      pos += 1;
      if (token.value !== 'ctx') {
        throw new Error(`Unknown identifier: ${token.value}`);
      }
      return req.body ? req.body.context : undefined;
    }
    if (consume('(')) {
      const value = parseExpression();
      expect(')');
      return value;
    }
    throw new Error('Expected expression');
  }

  const result = parseExpression();
  if (peek().type !== 'eof') throw new Error('Unexpected token');
  return result;
}

